package com.jarvis; import android.Manifest; import android.app.Activity; import android.content.Intent; import android.net.Uri; import android.os.Bundle; import android.provider.CalendarContract; import android.provider.ContactsContract; import android.speech.RecognizerIntent; import android.speech.tts.TextToSpeech; import android.telephony.SmsManager; import android.widget.Button; import android.widget.EditText; import android.widget.LinearLayout; import android.widget.ScrollView; import android.widget.TextView; import org.json.JSONArray; import org.json.JSONObject; import java.net.HttpURLConnection; import java.net.URL; import java.net.URLEncoder; import java.text.SimpleDateFormat; import java.util.Date; import java.util.Locale; class MainActivity : Activity(), TextToSpeech.OnInitListener { private lateinit var tts: TextToSpeech; private lateinit var out: TextView; private lateinit var input: EditText; private lateinit var keyBox: EditText; private val prefs by lazy { getSharedPreferences("jarvis", MODE_PRIVATE) }; override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); tts = TextToSpeech(this, this); val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(40, 80, 40, 40) }; keyBox = EditText(this).apply { hint = "Claude API anahtarı"; setText(prefs.getString("key", "")); setSingleLine() }; val saveBtn = Button(this).apply { text = "Anahtarı kaydet"; setOnClickListener { prefs.edit().putString("key", keyBox.text.toString().trim()).apply(); show("Kaydedildi.") } }; val micBtn = Button(this).apply { text = "🎤 Konuş"; setOnClickListener { startVoice() } }; input = EditText(this).apply { hint = "veya buraya yaz" }; val sendBtn = Button(this).apply { text = "Gönder"; setOnClickListener { handle(input.text.toString()) } }; out = TextView(this).apply { textSize = 16f }; root.addView(keyBox); root.addView(saveBtn); root.addView(micBtn); root.addView(input); root.addView(sendBtn); root.addView(ScrollView(this).apply { addView(out) }); setContentView(root); requestPermissions( arrayOf( Manifest.permission.READ_CONTACTS, Manifest.permission.CALL_PHONE, Manifest.permission.SEND_SMS ), 1 ) }; override fun onInit(status: Int) { tts.language = Locale("tr", "TR") }; private fun show(s: String) { runOnUiThread { out.text = s } }; private fun speak(s: String) { show(s); tts.speak(s, TextToSpeech.QUEUE_FLUSH, null, "j") }; private fun startVoice() { val i = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply { putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM); putExtra(RecognizerIntent.EXTRA_LANGUAGE, "tr-TR") }; try { startActivityForResult(i, 2) } catch (e: Exception) { show("Ses tanıma bulunamadı, yazarak dene.") } }; @Deprecated("Deprecated in Java") override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) { super.onActivityResult(requestCode, resultCode, data); if (requestCode == 2 && resultCode == RESULT_OK) { val text = data?.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)?.firstOrNull(); if (text != null) { input.setText(text); handle(text) } } }; private fun handle(text: String) { if (text.isBlank()) return; val key = prefs.getString("key", "") ?: ""; if (key.isEmpty()) { show("Önce API anahtarını girip kaydet."); return }; show("Düşünüyorum..."); Thread { try { val j = askClaude(key, text); runOnUiThread { act(j) } } catch (e: Exception) { show("Hata: ${e.message}") } }.start() }; private fun askClaude(key: String, text: String): JSONObject { val now = SimpleDateFormat("yyyy-MM-dd HH:mm EEEE", Locale("tr")).format(Date()); val system = "Sen Jarvis'sin, Türkçe konuşan telefon asistanısın. Kullanıcının komutunu " + "SADECE tek bir JSON nesnesi olarak yanıtla, başka hiçbir şey yazma. Biçim: " + "{\"action\":\"open_app|call|sms|youtube|reminder|say\"," + "\"target\":\"uygulama adı, kişi adı veya youtube arama sözcükleri\"," + "\"text\":\"sms metni, hatırlatma metni veya sana söylenen şeye kısa cevabın\"," + "\"minutes\":şimdiden kaç dakika sonra (sadece reminder için, sayı)}. " + "Şu an: $now"; val body = JSONObject() .put("model", "claude-sonnet-4-6") .put("max_tokens", 300) .put("system", system) .put( "messages", JSONArray().put( JSONObject().put("role", "user").put("content", text) ) ); val c = URL("https://api.anthropic.com/v1/messages").openConnection() as HttpURLConnection; c.requestMethod = "POST"; c.setRequestProperty("content-type", "application/json"); c.setRequestProperty("x-api-key", key); c.setRequestProperty("anthropic-version", "2023-06-01"); c.doOutput = true; c.outputStream.use { it.write(body.toString().toByteArray()) }; val stream = if (c.responseCode in 200..299) c.inputStream else c.errorStream; val resp = stream.bufferedReader().readText(); if (c.responseCode !in 200..299) throw Exception("API ${c.responseCode}: $resp"); val reply = JSONObject(resp).getJSONArray("content").getJSONObject(0).getString("text"); val s = reply.indexOf('{'); val e = reply.lastIndexOf('}'); return JSONObject(reply.substring(s, e + 1)) }; private fun act(j: JSONObject) { val target = j.optString("target"); val text = j.optString("text"); try { when (j.optString("action")) { "open_app" -> openApp(target); "youtube" -> { val q = URLEncoder.encode(target, "UTF-8"); startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("https://www.youtube.com/results?search_query=$q"))); show("YouTube'da açıyorum: $target") }; "call" -> { val n = findNumber(target); if (n == null) speak("$target rehberde bulunamadı.") else { startActivity(Intent(Intent.ACTION_CALL, Uri.parse("tel:$n"))); show("Arıyorum: $target") } }; "sms" -> { val n = findNumber(target); if (n == null) speak("$target rehberde bulunamadı.") else { val sms = getSystemService(SmsManager::class.java); sms.sendMultipartTextMessage(n, null, sms.divideMessage(text), null, null); speak("$target kişisine mesaj gönderdim.") } }; "reminder" -> { val start = System.currentTimeMillis() + j.optLong("minutes", 60) * 60_000; val i = Intent(Intent.ACTION_INSERT).apply { data = CalendarContract.Events.CONTENT_URI; putExtra(CalendarContract.Events.TITLE, text); putExtra(CalendarContract.EXTRA_EVENT_BEGIN_TIME, start); putExtra(CalendarContract.EXTRA_EVENT_END_TIME, start + 15 * 60_000) }; startActivity(i); show("Hatırlatma ekranı açıldı, kaydet'e bas: $text") }; else -> speak(text.ifEmpty { "Anlayamadım." }) } } catch (e: Exception) { show("Yapamadım: ${e.message}") } }; private fun openApp(name: String) { val pm = packageManager; val main = Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER); val match = pm.queryIntentActivities(main, 0).firstOrNull { it.loadLabel(pm).toString().contains(name, ignoreCase = true) }; if (match == null) { speak("$name uygulaması yüklü değil."); return }; startActivity(pm.getLaunchIntentForPackage(match.activityInfo.packageName)); show("Açıyorum: $name") }; private fun findNumber(name: String): String? { if (name.all { it.isDigit() || it == '+' || it == ' ' }) return name.replace(" ", ""); val cur = contentResolver.query( ContactsContract.CommonDataKinds.Phone.CONTENT_URI, arrayOf(ContactsContract.CommonDataKinds.Phone.NUMBER), "${ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME} LIKE ?", arrayOf("%$name%"), null ) ?: return null; cur.use { return if (it.moveToFirst()) it.getString(0) else null } } };
